using System;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Reflection;
class MeditationControllerTest {
 sealed class Fake:IMeditationRuntime {public Dictionary<int,bool> States=new Dictionary<int,bool>{{1,false},{2,false},{3,false}};public int Sends;public bool Ignore;public List<int> Recipients=new List<int>();public bool Sitting(CharacterRef c){return States[c.Pid];}public MeditationResult Set(CharacterRef c,bool sitting){Sends++;Recipients.Add(c.Pid);if(!Ignore)States[c.Pid]=sitting;return new MeditationResult();}}
 static void Check(bool ok,string s){if(!ok)throw new Exception(s);Console.WriteLine("PASS "+s);}static void Due(MeditationController c){var states=(IDictionary)typeof(MeditationController).GetField("attempts",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(c);foreach(var p in states.Values)p.GetType().GetField("Next").SetValue(p,DateTime.MinValue);}
 static int Main(){try{CharacterRef main=new CharacterRef{Pid=1,Id=1},sec=new CharacterRef{Pid=2,Id=2};var f=new Fake();var c=new MeditationController(f,new HashSet<int>(),s=>{});c.Tick(main,new[]{sec},true);Check(f.Sends==0,"personagens ja em pe nao recebem comando");f.States[1]=true;c.Tick(main,new[]{sec},true);Check(f.Sends==1&&f.States[2]&&c.Holds(2),"principal medita e secundario acompanha com seguir em espera");c.Tick(main,new[]{sec},true);c.Tick(main,new[]{sec},true);Check(f.Sends==1,"estado confirmado nao e reenviado continuamente");f.States[1]=false;c.Tick(main,new[]{sec},true);Check(f.Sends==2&&!f.States[2]&&c.Holds(2),"levantar e enviado e seguir aguarda confirmacao");c.Tick(main,new[]{sec},true);Check(!c.Holds(2),"confirmacao de levantar libera manutencao do seguir");Check(f.Recipients.All(pid=>pid==2),"principal nunca recebe comandos do espelhamento");f.States[1]=true;c.Tick(main,new[]{sec},false);Check(f.Sends==2,"opcao desligada nao envia meditacao");f.Ignore=true;c.Tick(main,new[]{sec},true);Due(c);c.Tick(main,new[]{sec},true);Due(c);c.Tick(main,new[]{sec},true);Due(c);c.Tick(main,new[]{sec},true);Check(f.Sends==5,"falha de confirmacao limita novas tentativas a tres");f.Ignore=false;f.States[1]=false;c.Tick(main,new[]{sec},true);f.States[1]=true;c.Tick(main,new[]{sec},true);Check(f.Sends==6&&f.States[2],"nova mudanca do principal permite nova tentativa");c.Tick(main,new[]{sec},true);f.States[2]=false;c.Tick(main,new[]{sec},true);Check(f.Sends==7,"interrupcao posterior do secundario volta a sincronizar");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
